<?php require __DIR__.'/app/bootstrap.php'; head('Sri Lanka residences','Explore curated residences and homes across Colombo, the south coast and Sri Lanka’s hill country.'); nav(); $list=property_rows(60); $region=strtolower(trim((string)($_GET['region']??''))); $regionNeedles=match($region){'colombo'=>['colombo'],'south-coast'=>['galle','matara','unawatuna','weligama','ahangama','talpe','bentota'],'hill-country'=>['kandy','badulla','ella','nuwara eli'],'east-coast'=>['trincomalee','batticaloa','passikudah'],'all'=>[],default=>[]}; if($regionNeedles)$list=array_values(array_filter($list,fn($p)=>array_filter($regionNeedles,fn($n)=>stripos($p['location'].' '.$p['district'].' '.$p['title'],$n)!==false)!==[])); $location=trim((string)($_GET['location']??'')); $q=trim((string)($_GET['q']??'')); $needle=$location?:$q; if($needle) $list=array_values(array_filter($list,fn($p)=>stripos($p['location'].' '.$p['district'].' '.$p['title'].' '.$p['category'],$needle)!==false)); ?>
<main class="listing-page"><section class="page-hero"><div class="section-index">A CONSIDERED COLLECTION · SRI LANKA</div><h1>Find a home<br><em>that feels like yours.</em></h1><p>Explore distinctive residences, from the energy of Colombo to the calm of the coast and hill country.</p></section><section class="listing-content section-pad"><form class="filter-bar" method="get"><label>Explore by place<input type="search" name="q" value="<?=e($q)?>" placeholder="City, coast or neighbourhood"></label><button class="button button-dark">Find a place <span>↗</span></button><span class="result-count"><?=count($list)?> considered residences</span></form><div class="property-grid listing-grid"><?php foreach($list as $p) property_card($p); ?></div></section></main><?php end_page(); ?>
